def minCost(nums1, nums2):
    # diff[v] = (count of v in nums1) - (count of v in nums2)
    diff = {}
    total = {}
    for x in nums1:
        diff[x] = diff.get(x, 0) + 1
        total[x] = total.get(x, 0) + 1
    for x in nums2:
        diff[x] = diff.get(x, 0) - 1
        total[x] = total.get(x, 0) + 1

    # Every value must appear an even number of times overall,
    # otherwise the two arrays can never hold equal multisets
    for v in total:
        if total[v] % 2 == 1:
            return -1

    # Each value with a surplus in nums1 of 2k must send k copies across.
    # Every cross swap fixes one such copy (paired with a surplus in nums2).
    cost = 0
    for v in diff:
        if diff[v] > 0:
            cost += diff[v] // 2
    return cost
